INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (23,0,'雨天想吃一碗热面（演示）','/imgs/demo/photos/pexels-12913665.jpg,/imgs/demo/photos/pexels-4913313.jpg,/imgs/demo/photos/pexels-9371714.jpg','<p><strong>【原创演示笔记】雨天想吃一碗热面</strong></p><p>场景：小巷杭帮菜（运河上街东街店）（演示），运河上街。参考预算约48元，实际收费需以店内说明为准。</p><p>工作日午休只有四十分钟，我选了靠窗的位置，先点小份面再加一碟蔬菜。汤面适合趁热吃，晚一点容易偏软。赶时间时建议先确认出餐时间。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',17,1000006,0,'2026-10-11 22:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (24,0,'两个人的铜锅晚饭怎么点（演示）','/imgs/demo/photos/pexels-4913313.jpg,/imgs/demo/photos/pexels-12913665.jpg,/imgs/demo/photos/pexels-18243195.jpg','<p><strong>【原创演示笔记】两个人的铜锅晚饭怎么点</strong></p><p>场景：南风铜锅（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约68元，实际收费需以店内说明为准。</p><p>这次按两人份搭配蔬菜和肉片，没有直接选大套餐。蘸料先少放，再按口味调整。小桌放满后有些拥挤，聚餐前可以问一下是否有宽一点的位置。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',18,1000007,0,'2026-10-11 12:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (25,0,'茶餐厅里的半小时午休（演示）','/imgs/demo/photos/pexels-17803244.jpg,/imgs/demo/photos/pexels-12913665.jpg,/imgs/demo/photos/pexels-7955383.jpg','<p><strong>【原创演示笔记】茶餐厅里的半小时午休</strong></p><p>场景：谷雨茶餐厅（大关商圈东街店）（演示），大关商圈。参考预算约88元，实际收费需以店内说明为准。</p><p>我的关注点是座位与出餐节奏，不是拍照。靠门位置比较热闹，想安静聊天可以往里坐。奶茶建议自行选择甜度，主食分量可以先问服务人员。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',19,1000008,0,'2026-10-11 02:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (26,0,'周末烤肉的点单备忘（演示）','/imgs/demo/photos/pexels-10587909.jpg,/imgs/demo/photos/pexels-12913665.jpg,/imgs/demo/photos/pexels-23940850.jpg','<p><strong>【原创演示笔记】周末烤肉的点单备忘</strong></p><p>场景：山禾日式食堂（拱墅万达东街店）（演示），拱墅万达。参考预算约118元，实际收费需以店内说明为准。</p><p>先点少量再加单比较好控制预算；不同肉片烤制时间不同，夹生的部分不要直接入口。吃完可以沿运河散步，店内味道较浓，外套放在收纳袋里更方便。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',20,1000009,0,'2026-10-10 16:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (27,0,'一个人吃饭也能认真一点（演示）','/imgs/demo/photos/pexels-9371714.jpg,/imgs/demo/photos/pexels-12913665.jpg,/imgs/demo/photos/pexels-5865422.jpg','<p><strong>【原创演示笔记】一个人吃饭也能认真一点</strong></p><p>场景：青柚轻食（水晶城东街店）（演示），水晶城。参考预算约158元，实际收费需以店内说明为准。</p><p>选小份套餐比临时拼几道菜省心。饭点前到店通常更从容，想吃清淡一点记得在下单时说明。我的预算含主食和一杯饮料，不含额外加菜。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',21,1000010,0,'2026-10-10 06:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (28,0,'四个人唱歌，小包间够不够（演示）','/imgs/demo/photos/pexels-18433815.jpg,/imgs/demo/photos/pexels-3475853.jpg,/imgs/demo/photos/pexels-7887036.jpg','<p><strong>【原创演示笔记】四个人唱歌，小包间够不够</strong></p><p>场景：声浪KTV（运河上街东街店）（演示），运河上街。参考预算约88元，实际收费需以店内说明为准。</p><p>这次关心的是包间大小和麦克风切换。先确认计费从入场还是开机开始，饮料与小食是否另收费用也要问清楚。唱歌间隙给嗓子留一点休息时间。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',37,1000009,0,'2026-10-11 21:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (29,0,'白天练歌比深夜聚会更适合我（演示）','/imgs/demo/photos/pexels-3475853.jpg,/imgs/demo/photos/pexels-18433815.jpg,/imgs/demo/photos/pexels-8827051.jpg','<p><strong>【原创演示笔记】白天练歌比深夜聚会更适合我</strong></p><p>场景：星河音乐空间（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约128元，实际收费需以店内说明为准。</p><p>周日下午的节奏比较轻松，我们把慢歌放在前面。预约时要确认到店时间与最晚结束时间，音量不必开得太高。短时段体验适合先熟悉点歌系统。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',38,1000010,0,'2026-10-11 11:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (30,0,'生日聚会前要确认的三件事（演示）','/imgs/demo/photos/pexels-4130659.jpg,/imgs/demo/photos/pexels-18433815.jpg,/imgs/demo/photos/pexels-6762300.jpg','<p><strong>【原创演示笔记】生日聚会前要确认的三件事</strong></p><p>场景：麦芽欢唱（大关商圈东街店）（演示），大关商圈。参考预算约168元，实际收费需以店内说明为准。</p><p>蛋糕能否自带、布置是否收费、人数上限，这三件事先问好。朋友迟到时可以安排轻松的背景音乐，不必一直唱。结账前核对额外服务项目。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',39,1000011,0,'2026-10-11 01:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (31,0,'歌单准备好，聚会少一点冷场（演示）','/imgs/demo/photos/pexels-18421575.jpg,/imgs/demo/photos/pexels-18433815.jpg,/imgs/demo/photos/pexels-28651424.jpg','<p><strong>【原创演示笔记】歌单准备好，聚会少一点冷场</strong></p><p>场景：蓝调练歌房（拱墅万达东街店）（演示），拱墅万达。参考预算约228元，实际收费需以店内说明为准。</p><p>每人先挑两首熟悉的歌曲，轮流唱比霸麦更有趣。合唱选大家都知道的副歌，包间里留出走动空间。预约成功后保存时间说明，避免临时改场。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',40,1000012,0,'2026-10-10 15:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (32,0,'下班后的两小时音乐时间（演示）','/imgs/demo/photos/pexels-7887036.jpg,/imgs/demo/photos/pexels-18433815.jpg,/imgs/demo/photos/pexels-3475853.jpg','<p><strong>【原创演示笔记】下班后的两小时音乐时间</strong></p><p>场景：音悦汇（水晶城东街店）（演示），水晶城。参考预算约38元，实际收费需以店内说明为准。</p><p>没有安排熬夜，唱完刚好赶上回程。建议看清时段套餐与超时单价，同行人少时无需追求大包间。若设备有杂音，可以直接请工作人员协助更换。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',41,1000013,0,'2026-10-10 05:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (33,0,'剪短发前，把参考图讲清楚（演示）','/imgs/demo/photos/pexels-39894501.jpg,/imgs/demo/photos/pexels-4969835.jpg,/imgs/demo/photos/pexels-3993309.jpg','<p><strong>【原创演示笔记】剪短发前，把参考图讲清楚</strong></p><p>场景：木槿发型工作室（运河上街东街店）（演示），运河上街。参考预算约158元，实际收费需以店内说明为准。</p><p>我准备了正面和侧面参考图，也说清楚每天愿意花多少时间打理。沟通长度比只说好看更有用。报价与是否含洗吹要在动剪刀前确认。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',57,1000012,0,'2026-10-11 20:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (34,0,'刘海修剪的小记录（演示）','/imgs/demo/photos/pexels-4969835.jpg,/imgs/demo/photos/pexels-39894501.jpg,/imgs/demo/photos/pexels-9146943.jpg','<p><strong>【原创演示笔记】刘海修剪的小记录</strong></p><p>场景：丝语造型（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约228元，实际收费需以店内说明为准。</p><p>这次只修刘海和发尾，没有做烫染。坐下后先观察光线，湿发与干发长度会有区别。赶时间可以预约简单项目，想保留长度要明确说出底线。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',58,1000013,0,'2026-10-11 10:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (35,0,'染发前先讨论维护成本（演示）','/imgs/demo/photos/pexels-4969838.jpg,/imgs/demo/photos/pexels-39894501.jpg,/imgs/demo/photos/pexels-7750098.jpg','<p><strong>【原创演示笔记】染发前先讨论维护成本</strong></p><p>场景：白茶理发馆（大关商圈东街店）（演示），大关商圈。参考预算约328元，实际收费需以店内说明为准。</p><p>我重点问了颜色褪去后的变化、补染周期和后续护理，不凭一张照片就下决定。有过敏史应先告知并按产品要求做相应测试，项目价格以书面说明为准。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',59,1000014,0,'2026-10-11 00:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (36,0,'日常通勤发型不必太复杂（演示）','/imgs/demo/photos/pexels-7750108.jpg,/imgs/demo/photos/pexels-39894501.jpg,/imgs/demo/photos/pexels-7750109.jpg','<p><strong>【原创演示笔记】日常通勤发型不必太复杂</strong></p><p>场景：橙光发廊（拱墅万达东街店）（演示），拱墅万达。参考预算约38元，实际收费需以店内说明为准。</p><p>希望早上梳好就能出门，因此把需求放在易打理上。发量与发质不同，参考图只能辅助沟通。完成后可以请发型师演示日常吹风的基本步骤。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',60,1000015,0,'2026-10-10 14:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (37,0,'第一次进发型工作室怎么沟通（演示）','/imgs/demo/photos/pexels-3993309.jpg,/imgs/demo/photos/pexels-39894501.jpg,/imgs/demo/photos/pexels-3993308.jpg','<p><strong>【原创演示笔记】第一次进发型工作室怎么沟通</strong></p><p>场景：轻风美发（水晶城东街店）（演示），水晶城。参考预算约68元，实际收费需以店内说明为准。</p><p>先讲预算，再讲希望保留的部分，最后确认项目清单。套餐外的护理应先问价格，不需要的项目直接拒绝。体验结束后记下实际耗时，方便下次预约。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',61,1000016,0,'2026-10-10 04:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (38,0,'第一次团课，先跟上节奏（演示）','/imgs/demo/photos/pexels-7031706.jpg,/imgs/demo/photos/pexels-17227606.jpg,/imgs/demo/photos/pexels-7031705.jpg','<p><strong>【原创演示笔记】第一次团课，先跟上节奏</strong></p><p>场景：起跑线健身（运河上街东街店）（演示），运河上街。参考预算约168元，实际收费需以店内说明为准。</p><p>到店前确认课程强度与新手适配情况，提前十分钟熟悉场地。动作不舒服时及时停下并问教练，不跟别人比重量。结束后留一点时间补水和休息。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',77,1000015,0,'2026-10-11 19:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (39,0,'攀岩初体验，安全流程比打卡重要（演示）','/imgs/demo/photos/pexels-4727163.jpg,/imgs/demo/photos/pexels-8028648.jpg,/imgs/demo/photos/pexels-7031706.jpg','<p><strong>【原创演示笔记】攀岩初体验，安全流程比打卡重要</strong></p><p>场景：蓝弧游泳馆（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约258元，实际收费需以店内说明为准。</p><p>先听场馆的安全讲解，再挑适合新手的路线。鞋子与保护装备按工作人员要求使用，不能凭视频自行模仿复杂动作。轮流尝试时注意落地区域。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',78,1000016,0,'2026-10-11 09:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (40,0,'羽毛球约场的小技巧（演示）','/imgs/demo/photos/pexels-35215418.jpg,/imgs/demo/photos/pexels-8028648.jpg,/imgs/demo/photos/pexels-29149073.jpg','<p><strong>【原创演示笔记】羽毛球约场的小技巧</strong></p><p>场景：轻跃普拉提（大关商圈东街店）（演示），大关商圈。参考预算约35元，实际收费需以店内说明为准。</p><p>先确认场地是按小时还是整场计费，球和球拍是否自备。热身后再开始对打，双打搭档沟通站位能减少碰撞。带一套替换衣服，回程舒服一些。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',79,1000017,0,'2026-10-10 23:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (41,0,'早晨练瑜伽的安静时段（演示）','/imgs/demo/photos/pexels-6689593.jpg,/imgs/demo/photos/pexels-7031706.jpg,/imgs/demo/photos/pexels-8028648.jpg','<p><strong>【原创演示笔记】早晨练瑜伽的安静时段</strong></p><p>场景：山岚攀岩（拱墅万达东街店）（演示），拱墅万达。参考预算约48元，实际收费需以店内说明为准。</p><p>我更看重通风和课程节奏，没有追求高难度体式。初次到课可以说明自己的身体限制，由老师判断是否适合参与。课后不急着走，给自己几分钟放松。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',80,1000018,0,'2026-10-10 13:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (42,0,'游泳体验前的装备清单（演示）','/imgs/demo/photos/pexels-8796050.jpg,/imgs/demo/photos/pexels-17227606.jpg,/imgs/demo/photos/pexels-4727163.jpg','<p><strong>【原创演示笔记】游泳体验前的装备清单</strong></p><p>场景：飞羽羽毛球馆（水晶城东街店）（演示），水晶城。参考预算约78元，实际收费需以店内说明为准。</p><p>泳帽、泳镜与更衣用品提前准备，入场前确认开放泳道和安全规则。不会游泳应选择有指导的课程，不独自进入深水区。场馆卫生和救生配置是重点。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',81,1000019,0,'2026-10-10 03:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (43,0,'下班后的足浴体验备忘（演示）','/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-7598366.jpg,/imgs/demo/photos/pexels-5240676.jpg','<p><strong>【原创演示笔记】下班后的足浴体验备忘</strong></p><p>场景：竹里足道（运河上街东街店）（演示），运河上街。参考预算约258元，实际收费需以店内说明为准。</p><p>我先确认水温和项目时长，感觉不适时直接提出调整。这里记录的是休闲体验，不是治疗建议。预约前看清项目是否包含加钟，结账时再核对一次。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',97,1000018,0,'2026-10-11 18:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (44,0,'安静环境比项目多更重要（演示）','/imgs/demo/photos/pexels-7598366.jpg,/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-5240640.jpg','<p><strong>【原创演示笔记】安静环境比项目多更重要</strong></p><p>场景：舒缓小筑（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约49元，实际收费需以店内说明为准。</p><p>想休息时，我会先问包间是否独立、背景音乐能否调低。个人用品与毛巾的更换流程可以当面确认。无需因为推荐就叠加多个项目，选择适合自己的时长。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',98,1000019,0,'2026-10-11 08:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (45,0,'周末约足疗，先看费用说明（演示）','/imgs/demo/photos/pexels-9146365.jpg,/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-5240642.jpg','<p><strong>【原创演示笔记】周末约足疗，先看费用说明</strong></p><p>场景：松间足浴（大关商圈东街店）（演示），大关商圈。参考预算约78元，实际收费需以店内说明为准。</p><p>同样写着六十分钟，是否包含等候与准备时间可能不同。预约时把人数和到店时间讲清楚，不适合的力度及时反馈。消费凭证留好，方便核对明细。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',99,1000020,0,'2026-10-10 22:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (46,0,'只想短暂休息的一次体验（演示）','/imgs/demo/photos/pexels-9146382.jpg,/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-5240641.jpg','<p><strong>【原创演示笔记】只想短暂休息的一次体验</strong></p><p>场景：清泉休闲（拱墅万达东街店）（演示），拱墅万达。参考预算约98元，实际收费需以店内说明为准。</p><p>没有追求很长的套餐，主要留意座椅舒适度与室内温度。若身体不舒服或有特殊情况，应先确认能否参与相关项目。休闲服务不能代替正规医疗。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',100,1000021,0,'2026-10-10 12:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (47,0,'双人体验怎么安排更从容（演示）','/imgs/demo/photos/pexels-5240676.jpg,/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-5240677.jpg','<p><strong>【原创演示笔记】双人体验怎么安排更从容</strong></p><p>场景：沐禾按摩（水晶城东街店）（演示），水晶城。参考预算约138元，实际收费需以店内说明为准。</p><p>一起预约时确认是否能同时开始，以及房间安排。先喝少量温水，时间结束后缓一会儿再走。提前确定预算，额外项目需要双方同意再选择。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',101,1000022,0,'2026-10-10 02:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (48,0,'把一小时留给安静的SPA空间（演示）','/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-7598366.jpg,/imgs/demo/photos/pexels-6899538.jpg','<p><strong>【原创演示笔记】把一小时留给安静的SPA空间</strong></p><p>场景：溪畔SPA（运河上街东街店）（演示），运河上街。参考预算约98元，实际收费需以店内说明为准。</p><p>这次关注的是灯光、温度和流程沟通。开始前先说明是否对香氛或护肤品敏感，不喜欢的味道可以明确拒绝。体验是放松场景，没有所谓必然的疗效。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',117,1000021,0,'2026-10-11 17:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (49,0,'首次做护理，先读项目清单（演示）','/imgs/demo/photos/pexels-7598366.jpg,/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-36837604.jpg','<p><strong>【原创演示笔记】首次做护理，先读项目清单</strong></p><p>场景：莲间水疗（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约138元，实际收费需以店内说明为准。</p><p>预约时问清洁面、护理与休息的时间各占多少，避免把等待算进体验。护肤品信息可以先了解，容易敏感时不随意尝试新产品。预算与项目范围提前确认。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',118,1000022,0,'2026-10-11 07:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (50,0,'芳香空间的选择记录（演示）','/imgs/demo/photos/pexels-6899549.jpg,/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-35884502.jpg','<p><strong>【原创演示笔记】芳香空间的选择记录</strong></p><p>场景：青檀芳香空间（大关商圈东街店）（演示），大关商圈。参考预算约168元，实际收费需以店内说明为准。</p><p>比起浓烈气味，我更喜欢通风与柔和光线。项目开始前先沟通是否使用香氛，有过敏史应谨慎选择。这里是原创演示记录，不是实际商家的效果评价。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',119,1000003,0,'2026-10-10 21:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (51,0,'双人水疗预约的注意事项（演示）','/imgs/demo/photos/pexels-6899551.jpg,/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-9146385.jpg','<p><strong>【原创演示笔记】双人水疗预约的注意事项</strong></p><p>场景：露水护理馆（拱墅万达东街店）（演示），拱墅万达。参考预算约198元，实际收费需以店内说明为准。</p><p>先确认独立空间、可预约时段与改期规则。两个人的偏好不同，不必选完全相同的服务；任何不舒服的环节都应停止。服务介绍和最终消费清单要一致。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',120,1000004,0,'2026-10-10 11:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (52,0,'周末慢下来，但不冲动办卡（演示）','/imgs/demo/photos/pexels-6899538.jpg,/imgs/demo/photos/pexels-11774389.jpg,/imgs/demo/photos/pexels-6899532.jpg','<p><strong>【原创演示笔记】周末慢下来，但不冲动办卡</strong></p><p>场景：栖云SPA（水晶城东街店）（演示），水晶城。参考预算约268元，实际收费需以店内说明为准。</p><p>单次体验更适合了解环境与服务流程，先不做大额预付。询问清楚取消预约的条件，用品是否一次性或清洁更换。护理体验因人而异，不用宣传词替代判断。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',121,1000005,0,'2026-10-10 01:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (53,0,'亲子手作，把时间留给孩子（演示）','/imgs/demo/photos/pexels-8926842.jpg,/imgs/demo/photos/pexels-8430255.jpg,/imgs/demo/photos/pexels-8430349.jpg','<p><strong>【原创演示笔记】亲子手作，把时间留给孩子</strong></p><p>场景：小鹿探索乐园（运河上街东街店）（演示），运河上街。参考预算约48元，实际收费需以店内说明为准。</p><p>选了流程简单的手作主题，没有要求成品一定漂亮。提前问适用年龄与是否需要家长陪同，小零件注意看管。衣服可以选耐脏一点的，现场节奏以孩子为主。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',137,1000004,0,'2026-10-11 16:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (54,0,'积木空间适合慢慢探索（演示）','/imgs/demo/photos/pexels-30225335.jpg,/imgs/demo/photos/pexels-30225337.jpg,/imgs/demo/photos/pexels-30225360.jpg','<p><strong>【原创演示笔记】积木空间适合慢慢探索</strong></p><p>场景：纸飞机手作馆（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约68元，实际收费需以店内说明为准。</p><p>我更关心不同年龄区是否分开、材料如何清洁。进入前说明活动规则，离开时带孩子一起收纳。若当天人多，可以先做安静的小任务再参加集体活动。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',138,1000005,0,'2026-10-11 06:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (55,0,'儿童乐园半日安排（演示）','/imgs/demo/photos/pexels-8429900.jpg,/imgs/demo/photos/pexels-8926842.jpg,/imgs/demo/photos/pexels-30225337.jpg','<p><strong>【原创演示笔记】儿童乐园半日安排</strong></p><p>场景：彩虹积木空间（大关商圈东街店）（演示），大关商圈。参考预算约98元，实际收费需以店内说明为准。</p><p>先看开放时间和身高年龄限制，不把行程排得太满。补水、休息和卫生间位置都提前熟悉，家长不要只顾拍照。食品能否带入以现场规定为准。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',139,1000006,0,'2026-10-10 20:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (56,0,'陶艺体验不必急着做完（演示）','/imgs/demo/photos/pexels-37361768.jpg,/imgs/demo/photos/pexels-30225337.jpg,/imgs/demo/photos/pexels-4241344.jpg','<p><strong>【原创演示笔记】陶艺体验不必急着做完</strong></p><p>场景：星球亲子工坊（拱墅万达东街店）（演示），拱墅万达。参考预算约158元，实际收费需以店内说明为准。</p><p>从揉泥开始比直接追求复杂造型更有参与感。烧制、上釉与取件时间要提前问，成品不能当天带走时保存凭证。桌面操作时陪孩子注意工具使用。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',140,1000007,0,'2026-10-10 10:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (57,0,'绘画课旁听的一点观察（演示）','/imgs/demo/photos/pexels-19230245.jpg,/imgs/demo/photos/pexels-8926842.jpg,/imgs/demo/photos/pexels-30225342.jpg','<p><strong>【原创演示笔记】绘画课旁听的一点观察</strong></p><p>场景：树屋故事馆（水晶城东街店）（演示），水晶城。参考预算约228元，实际收费需以店内说明为准。</p><p>我们选短时体验课，看看孩子是否喜欢环境。关注老师怎样引导表达，而不是比较谁画得像。材料是否另收费、陪同位置和结束时间都应先确认。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',141,1000008,0,'2026-10-10 00:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (58,0,'不喝酒也可以坐坐的清吧（演示）','/imgs/demo/photos/pexels-1398266.jpg,/imgs/demo/photos/pexels-26261299.jpg,/imgs/demo/photos/pexels-31682340.jpg','<p><strong>【原创演示笔记】不喝酒也可以坐坐的清吧</strong></p><p>场景：微醺小岛（运河上街东街店）（演示），运河上街。参考预算约98元，实际收费需以店内说明为准。</p><p>我选无酒精饮品，先问清是否存在最低消费。聊天更适合较安静的位置，音乐响起后可以换个时段再来。晚间出门安排好回程，饮酒后不要驾驶。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',157,1000007,0,'2026-10-11 15:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (59,0,'听爵士的晚上，提前选好座位（演示）','/imgs/demo/photos/pexels-26261299.jpg,/imgs/demo/photos/pexels-1398266.jpg,/imgs/demo/photos/pexels-10375846.jpg','<p><strong>【原创演示笔记】听爵士的晚上，提前选好座位</strong></p><p>场景：月光音乐酒馆（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约138元，实际收费需以店内说明为准。</p><p>演出时段与普通营业时间可能不同，入场前确认座位与费用。我们把手机音量调低，尽量不影响别人听歌。点饮品按个人需求来，不为氛围勉强饮酒。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',158,1000008,0,'2026-10-11 05:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (60,0,'精酿初体验先从小杯了解（演示）','/imgs/demo/photos/pexels-15750727.jpg,/imgs/demo/photos/pexels-1398266.jpg,/imgs/demo/photos/pexels-31206785.jpg','<p><strong>【原创演示笔记】精酿初体验先从小杯了解</strong></p><p>场景：青橘清吧（大关商圈东街店）（演示），大关商圈。参考预算约188元，实际收费需以店内说明为准。</p><p>选择小杯更方便了解风味，饮品度数与价格提前看清。未成年人不应饮酒，成年人也要控制量。晚间消费之后选择公共交通或正规代驾返程。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',159,1000009,0,'2026-10-10 19:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (61,0,'朋友聊天的夜间小角落（演示）','/imgs/demo/photos/pexels-34774319.jpg,/imgs/demo/photos/pexels-1398266.jpg,/imgs/demo/photos/pexels-7708508.jpg','<p><strong>【原创演示笔记】朋友聊天的夜间小角落</strong></p><p>场景：留白酒廊（拱墅万达东街店）（演示），拱墅万达。参考预算约258元，实际收费需以店内说明为准。</p><p>相比拍照，我更喜欢不用提高声音的座位。问清服务费与预约保留时间，迟到时主动联系店员。这里描述的是演示场景，没有实际到店消费记录。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',160,1000010,0,'2026-10-10 09:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (62,0,'把夜生活缩短成一个轻松时段（演示）','/imgs/demo/photos/pexels-31682340.jpg,/imgs/demo/photos/pexels-1398266.jpg,/imgs/demo/photos/pexels-31970850.jpg','<p><strong>【原创演示笔记】把夜生活缩短成一个轻松时段</strong></p><p>场景：星野精酿（水晶城东街店）（演示），水晶城。参考预算约48元，实际收费需以店内说明为准。</p><p>没有安排转场，坐一会儿就回家。无酒精菜单和热饮选择也值得提前问问。同行人彼此照应，个人物品放在视线范围内，不接受来历不明的饮品。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',161,1000011,0,'2026-10-09 23:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (63,0,'六个朋友的周末桌游局（演示）','/imgs/demo/photos/pexels-6032656.jpg,/imgs/demo/photos/pexels-8111307.jpg,/imgs/demo/photos/pexels-7404543.jpg','<p><strong>【原创演示笔记】六个朋友的周末桌游局</strong></p><p>场景：纸飞机聚会馆（运河上街东街店）（演示），运河上街。参考预算约138元，实际收费需以店内说明为准。</p><p>我们先挑规则简单的合作游戏，熟悉后再换更复杂的。预约时确认房间人数上限、桌游清单与结束时间，饮料小食是否收费也要问清楚。聚会以大家都能参与为主。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',177,1000010,0,'2026-10-11 14:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (64,0,'生日轰趴先做一份分工表（演示）','/imgs/demo/photos/pexels-8111307.jpg,/imgs/demo/photos/pexels-6032656.jpg,/imgs/demo/photos/pexels-36079211.jpg','<p><strong>【原创演示笔记】生日轰趴先做一份分工表</strong></p><p>场景：周末派对屋（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约188元，实际收费需以店内说明为准。</p><p>有人负责带蛋糕，有人准备音乐，还有人安排回程。布置、自带食品和清洁费用都提前确认，不临时把费用交给一个人承担。活动结束后一起整理空间。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',178,1000011,0,'2026-10-11 04:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (65,0,'有厨房的聚会空间怎么选（演示）','/imgs/demo/photos/pexels-8111367.jpg,/imgs/demo/photos/pexels-8111307.jpg,/imgs/demo/photos/pexels-36079211.jpg','<p><strong>【原创演示笔记】有厨房的聚会空间怎么选</strong></p><p>场景：橙子桌游空间（大关商圈东街店）（演示），大关商圈。参考预算约258元，实际收费需以店内说明为准。</p><p>先确认是否允许自己做饭、厨具清洁与食材存放要求。不会使用的设备先问工作人员，不擅自接电或操作。餐后清洁范围和押金退还规则应写清楚。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',179,1000012,0,'2026-10-10 18:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (66,0,'不赶场的一次朋友聚会（演示）','/imgs/demo/photos/pexels-16256067.jpg,/imgs/demo/photos/pexels-6032656.jpg,/imgs/demo/photos/pexels-32684295.jpg','<p><strong>【原创演示笔记】不赶场的一次朋友聚会</strong></p><p>场景：树屋朋友客厅（拱墅万达东街店）（演示），拱墅万达。参考预算约48元，实际收费需以店内说明为准。</p><p>预留聊天时间比把所有娱乐项目都试一遍更轻松。桌游、观影与用餐区能否同时使用要先确认，夜间控制音量，避免影响周边。临时增加人数先征求场馆同意。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',180,1000013,0,'2026-10-10 08:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (67,0,'雨天聚会的室内备选（演示）','/imgs/demo/photos/pexels-7404543.jpg,/imgs/demo/photos/pexels-6032656.jpg,/imgs/demo/photos/pexels-27381460.jpg','<p><strong>【原创演示笔记】雨天聚会的室内备选</strong></p><p>场景：星光聚会馆（水晶城东街店）（演示），水晶城。参考预算约68元，实际收费需以店内说明为准。</p><p>关注交通与活动区大小，先问清改期规则。设备发生故障时联系工作人员，不自行拆修。预算按场地、餐饮和额外服务分别计算，离开前核对个人物品。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',181,1000014,0,'2026-10-09 22:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (68,0,'第一次美甲，先从简单配色开始（演示）','/imgs/demo/photos/pexels-13068380.jpg,/imgs/demo/photos/pexels-36328527.jpg,/imgs/demo/photos/pexels-18112334.jpg','<p><strong>【原创演示笔记】第一次美甲，先从简单配色开始</strong></p><p>场景：指尖花园（运河上街东街店）（演示），运河上街。参考预算约198元，实际收费需以店内说明为准。</p><p>我带了日常衣服的颜色作参考，没有叠加很多装饰。项目包含卸甲还是需要另付费要先确认，工具清洁也值得留意。喜欢的款式可以讨论是否适合自己的指甲长度。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',197,1000013,0,'2026-10-11 13:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (69,0,'短甲也能有清爽的细节（演示）','/imgs/demo/photos/pexels-36328527.jpg,/imgs/demo/photos/pexels-13068380.jpg,/imgs/demo/photos/pexels-6135681.jpg','<p><strong>【原创演示笔记】短甲也能有清爽的细节</strong></p><p>场景：月牙美甲（远洋乐堤港东街店）（演示），远洋乐堤港。参考预算约258元，实际收费需以店内说明为准。</p><p>这次重点是修形与单色，工作时更方便。操作过程中不舒服要及时反馈，不为了拍照勉强选择很长的款式。预约前问清预计时间，给自己留一点缓冲。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',198,1000014,0,'2026-10-11 03:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (70,0,'美睫体验前的沟通清单（演示）','/imgs/demo/photos/pexels-34132695.jpg,/imgs/demo/photos/pexels-13068380.jpg,/imgs/demo/photos/pexels-7755296.jpg','<p><strong>【原创演示笔记】美睫体验前的沟通清单</strong></p><p>场景：白桃甲艺（大关商圈东街店）（演示），大关商圈。参考预算约38元，实际收费需以店内说明为准。</p><p>先说明是否容易敏感，以及平时是否戴眼镜。材料、款式和操作步骤需要由工作人员讲清楚，有不适及时停止。这里记录的是演示场景，不承诺实际效果或持久时间。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',199,1000015,0,'2026-10-10 17:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (71,0,'换季想换一个低调的甲色（演示）','/imgs/demo/photos/pexels-38194465.jpg,/imgs/demo/photos/pexels-36930354.jpg,/imgs/demo/photos/pexels-34132695.jpg','<p><strong>【原创演示笔记】换季想换一个低调的甲色</strong></p><p>场景：猫眼美睫（拱墅万达东街店）（演示），拱墅万达。参考预算约68元，实际收费需以店内说明为准。</p><p>在自然光下比较色卡，更容易判断实际观感。询问补修和卸除的收费范围，避免只看低价套餐的标题。把消费项目写清楚，不临时追加自己不需要的装饰。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',200,1000016,0,'2026-10-10 07:36:41.000000','2026-10-11 23:36:12.000000');
INSERT INTO `tb_blog` (`id`,`liked`,`title`,`images`,`content`,`shop_id`,`user_id`,`comments`,`create_time`,`update_time`) VALUES (72,0,'两个人一起预约的美甲时间（演示）','/imgs/demo/photos/pexels-18112334.jpg,/imgs/demo/photos/pexels-13068380.jpg,/imgs/demo/photos/pexels-6135685.jpg','<p><strong>【原创演示笔记】两个人一起预约的美甲时间</strong></p><p>场景：青柠美甲（水晶城东街店）（演示），水晶城。参考预算约98元，实际收费需以店内说明为准。</p><p>提前说明人数与项目，不一定能够同时结束。复杂图案应先确认是否能做及费用，参考图只用于沟通。保持舒适的坐姿，操作完成后按工作人员说明进行日常护理。</p><p>本文为学习项目编写的模拟内容，未在上述门店发生实际消费；配图来自Pexels摄影素材，仅作场景演示，非本店实景，也不代表图中人物的推荐。</p>',201,1000017,0,'2026-10-09 21:36:41.000000','2026-10-11 23:36:12.000000');
